package com.oai.harmonywake; import android.content.*; import android.os.*; public class AlarmReceiver extends BroadcastReceiver { static PowerManager.WakeLock lock; public void onReceive(Context c,Intent i){int id=i.getIntExtra("task_id",-1);WakeTask t=TaskStore.find(c,id);if(t==null||!t.enabled)return;long d=Math.max(1,t.screenMinutes)*60000L;try{PowerManager pm=(PowerManager)c.getSystemService(Context.POWER_SERVICE);if(lock!=null&&lock.isHeld())lock.release();lock=pm.newWakeLock(PowerManager.SCREEN_BRIGHT_WAKE_LOCK|PowerManager.ACQUIRE_CAUSES_WAKEUP|PowerManager.ON_AFTER_RELEASE,"HarmonyWake:Screen");lock.acquire(d);}catch(Exception e){}Intent w=new Intent(c,WakeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP).putExtra("task_id",id);c.startActivity(w);AlarmScheduler.schedule(c,t);}}